\label{thm:A}
For every $\alpha\in[0,2]$, the graph parameter $\vartheta_\alpha$ belongs to the
entanglement-assisted asymptotic spectrum $X(\mathcal G,\le_*)$.

\label{thm:B}
For $\tfrac12\le\alpha\le2$ we have $\vartheta_\alpha(C_5)=\tfrac52$.  For
$0\le\alpha\le\tfrac12$, writing $p=1/(1-\alpha)\in[1,2]$,
\begin{equation}\label{eq:pentagon-intro}
 \sqrt5\left(\frac{\sqrt5}{2}\right)^{p-1}
 \ \le\ \vartheta_\alpha(C_5)\ \le\
 \min\left\{\frac52,\ \sqrt5\cdot5^{(p-1)/2}\right\}.
\end{equation}
The map $\alpha\mapsto\vartheta_\alpha(C_5)$ is continuous and carries
$[0,\tfrac12]$ onto $[\sqrt5,\tfrac52]$.  In particular $X(\mathcal G,\le_*)$ contains
continuum many distinct points of the form $\vartheta_\alpha$.

\label[definition]{def:theta-alpha}
For a graph $G$ and $\alpha\in[0,2]$, define $\vartheta_\alpha(G)$ by
\begin{equation}\label{eq:def-parameter}
 \log\vartheta_\alpha(G)
 =\inf\Bigl\{\max_{x}D_\alpha(\rho_x\Vert\sigma)\ :\
   (\rho_x)\text{ compatible with }G,\ \sigma\text{ faithful}\Bigr\},
\end{equation}
where the states live on a common Hilbert space of any finite dimension.  For
the null graph we set $\vartheta_\alpha(K_0)=0$.

\label[lemma]{lem:flat}
If $(\rho,\sigma)$ is flat, then $D_\alpha(\rho\Vert\sigma)=-\log\operatorname{Tr}\Pi\sigma$
for every $\alpha\in[0,2]$.

\label[proposition]{prop:continuity}
For every graph $G$, the map $\alpha\mapsto\vartheta_\alpha(G)$ is continuous on
$[0,1)$.

\label[lemma]{lem:orthogonal-sum}
If $Q_1,\dots,Q_m$ are mutually orthogonal nonzero projections, $\sigma$ is a faithful
state and $s\in[-1,1]$, then $\sum_jZ_s(\sigma,Q_j)\le1$.

\label[lemma]{lem:trace}
For every representation of $C_5$ and every operator $X$,
$\sum_i\lVert P_iXP_i\rVert_1\le\sqrt5\,\lVert X\rVert_1$.

\label{thm:pentagon-bounds}
For $0\le\alpha\le\frac12$ and $p=1/(1-\alpha)$, the bounds
\eqref{eq:pentagon-intro} hold.

\label[corollary]{cor:middle}
For every graph $G$, $S_{0,\mathrm{NS}}(G)=\log\Sigma(G)$.  There is a graph with
$C_{\min}(G)<S_{0,\mathrm{NS}}(G)$.

\label[lemma]{lem:anticomm}
If $X$ and $Y$ are Hermitian unitaries on $\mathbb C^d$, then
$\lvert\operatorname{Tr} X\rvert\le\operatorname{rank}(XY+YX)$.

\label[lemma]{lem:rank-ineq}
Let $(P_v)$ be projections on $\mathbb C^d$, one for each vertex of $F$, with
$P_vP_w=0$ whenever $v\ne w$ are non-adjacent; zero projections are allowed.
For each context $c$ put $S_c=\sum_{v\in c}P_v$.  Then
\begin{equation}\label{eq:rank-ineq}
 4\tau(P_0)+7\tau(S_0)+11\tau(S_1)+9\tau(S_2)
 +11\tau(S_3)+11\tau(S_4)+9\tau(S_5)\le59,
\end{equation}
with equality for the magic-square representation $(Q_v)$.
